    public readonly struct MeloTrack
    {
        private readonly IntPtr _instance;
        private readonly int _bus;
        public int Index { get; }
        internal MeloTrack(IntPtr instance, int index, int bus) { _instance = instance; Index = index; _bus = bus; }
        public bool IsValid => Native.melo_owner_is_valid(_instance, Index, _bus) != 0;
        public string Name { get { IntPtr instance = _instance; int index = Index, bus = _bus; return Native.Text((buffer, size) => Native.melo_owner_name(instance, index, bus, buffer, size)); } }
        public float Volume { get => Native.melo_owner_get_volume(_instance, Index, _bus); set => Native.melo_owner_set_volume(_instance, Index, _bus, value); }
        public float Pan { get => Native.melo_owner_get_pan(_instance, Index, _bus); set => Native.melo_owner_set_pan(_instance, Index, _bus, value); }
        public bool Muted { get => Native.melo_owner_get_muted(_instance, Index, _bus) != 0; set => Native.melo_owner_set_muted(_instance, Index, _bus, value ? 1 : 0); }
        public bool Solo { get => Native.melo_owner_get_solo(_instance, Index, _bus) != 0; set => Native.melo_owner_set_solo(_instance, Index, _bus, value ? 1 : 0); }
        public float SendA { get => Native.melo_owner_get_senda(_instance, Index, _bus); set => Native.melo_owner_set_senda(_instance, Index, _bus, value); }
        public float SendB { get => Native.melo_owner_get_sendb(_instance, Index, _bus); set => Native.melo_owner_set_sendb(_instance, Index, _bus, value); }
        /// <summary>Serialized instrument settings. Null clears the instrument.</summary>
        public void SetInstrument(string instrumentJson) => Native.melo_track_set_instrument_json(_instance, Index, instrumentJson);
        public string Instrument { get { IntPtr instance = _instance; int index = Index; return Native.Text((buffer, size) => Native.melo_track_instrument_json(instance, index, buffer, size)); } }
        public int EffectCount => Native.melo_owner_effect_count(_instance, Index, _bus);
        public IEnumerable<MeloEffect> Effects { get { for (int i = 0; i < EffectCount; i++) yield return MeloEffect.Create(_instance, Index, _bus, i); } }
        public T GetEffect<T>() where T : MeloEffect
        { int index = Native.melo_owner_find_effect(_instance, Index, _bus, MeloEffect.TypeFor<T>()); return index < 0 ? null : (T)MeloEffect.Create(_instance, Index, _bus, index); }
        public bool TryGetEffect<T>(out T effect) where T : MeloEffect { effect = GetEffect<T>(); return effect != null; }
        public bool HasEffect<T>() where T : MeloEffect => GetEffect<T>() != null;
        public T AddEffect<T>() where T : MeloEffect
        {
            if (!IsValid) throw new InvalidOperationException("Track or bus is invalid.");
            int index = Native.melo_owner_add_effect(_instance, Index, _bus, MeloEffect.TypeFor<T>());
            return index < 0 ? null : (T)MeloEffect.Create(_instance, Index, _bus, index);
        }
        public bool RemoveEffect<T>() where T : MeloEffect => Native.melo_owner_remove_effect(_instance, Index, _bus, MeloEffect.TypeFor<T>()) != 0;
    }
